INSERT INTO `email_templates` (`id`, `type`, `name`, `slug`, `audience`, `subject`, `body`, `attachment_path`, `attachment_name`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'visitor_invitation', 'Visitor Invitation', 'visitor_invitation', 'visitor', 'You have been invited to {{app_name}}', '<h2>Hello {{recipient_name}}!</h2><p>You have been invited to {{app_name}}.</p><p><a href=\"{{button_url}}\">{{cta_label}}</a></p><p>Thanks,<br>{{app_name}}</p>', NULL, NULL, '2025-11-19 08:45:19', '2025-11-20 03:11:40', NULL),
(2, 'company_invitation', 'Company User Invitation', 'company_invitation', 'company', 'You have been invited to {{company_name}} on {{app_name}}', '<h2>Hello {{recipient_name}}!</h2>\r\n<p>{{company_name}} has invited you to collaborate inside {{app_name}}.</p>\r\n<p><a href=\"{{button_url}}\" style=\"background:#0073AF;color:#ffffff;padding:10px 18px;border-radius:999px;text-decoration:none;display:inline-block;\">{{cta_label}}</a></p>\r\n<p>If you were not expecting this email please ignore it.</p>\r\n<p>Regards,<br>{{company_name}} &amp; {{app_name}}</p>', NULL, NULL, '2025-11-19 08:45:19', '2025-11-19 08:45:19', NULL),
(3, 'visit_approved_visitor', 'Visit Approved - Visitor Notification', 'visit_approved_visitor', 'visitor', 'Your visit has been approved - {{app_name}}', '<h2>Hello {{visitor_name}}!</h2><p>Great news! Your visit request has been approved.</p><p><strong>Visit Details:</strong></p><p><strong>Visit&nbsp;Id:</strong> {{visit_id}}</p><p><strong>Branch:</strong> {{branch_name}}</p><ul><li><strong>Visit Date &amp; Time:</strong> {{visit_date}}</li><li><strong>Approved By:</strong> {{approved_by}}</li></ul><p>&nbsp;</p><p>Please make sure to arrive on time. If you need to make any changes, please contact us.</p><p>Best regards,<br>{{app_name}}</p>', NULL, NULL, '2025-11-21 01:12:50', '2025-11-21 22:35:25', NULL),
(4, 'visit_approved_admin', 'Visit Approved - Admin Notification', 'visit_approved_admin', 'visitor', 'Visit approved for {{visitor_name}} - {{app_name}}', '<h2>Hello Admin!</h2><p>A visit request has been approved by {{approver_name}}.</p><p><strong>Visit Details:</strong></p><p><strong>Visit Id:</strong> {{visit_id}}</p><ul><li><strong>Visitor:</strong> {{visitor_name}} ({{visitor_email}})</li><li><strong>Company:</strong> {{company_name}}</li><li><strong>Branch:</strong> {{branch_name}}</li><li><strong>Visit Date &amp; Time:</strong> {{visit_date}}</li><li><strong>Status:</strong> {{status}}</li><li><strong>Approved By:</strong> {{approved_by}}</li></ul><p><strong>Notes:</strong> {{notes}}</p><p>&nbsp;</p><p>This is an automated notification from {{app_name}}.</p><p>Best regards,<br>{{app_name}}</p>', NULL, NULL, '2025-11-21 01:12:50', '2025-11-21 22:35:23', NULL),
(5, 'reset_password', 'Password Reset Request', 'reset_password', 'visitor', 'Reset your password - {{app_name}}', '<h2>Hello {{user_name}}!</h2><p>You are receiving this email because we received a password reset request for your account.</p><p><a href=\"{{reset_url}}\">{{cta_label}}</a></p><p>This password reset link will expire in {{expiry_time}} minutes.</p><p>If you did not request a password reset, no further action is required. Your password will remain unchanged.</p><p>For security reasons, please do not share this link with anyone.</p><p>Best regards,<br>{{app_name}}</p>', NULL, NULL, '2025-11-21 01:12:50', '2025-11-21 06:03:23', NULL),
(6, 'new_visit', 'New Visit Created', 'new_visit', 'visitor', 'New Visit Available - {{branch_name}}', '<h2>New Visit Opportunity!</h2>\r\n<p>A new visit has been created and is now available.</p>\r\n\r\n<h3>Visit Details:</h3>\r\n<ul>\r\n    <li><strong>Branch:</strong> {{branch_name}}</li>\r\n    <li><strong>Company:</strong> {{company_name}}</li>\r\n    <li><strong>Questionnaire:</strong> {{questionnaire_name}}</li>\r\n    <li><strong>Start Date:</strong> {{start_datetime}}</li>\r\n    <li><strong>End Date:</strong> {{end_datetime}}</li>\r\n    <li><strong>Price:</strong> {{price}}</li>\r\n    <li><strong>Expense Estimate:</strong> {{expense_estimation}}</li>\r\n</ul>\r\n\r\n<p>{{description}}</p>\r\n\r\n<p><a href=\"{{button_url}}\" style=\"background:#0073AF;color:#ffffff;padding:10px 18px;border-radius:999px;text-decoration:none;display:inline-block;\">{{cta_label}}</a></p>\r\n\r\n<p>This is a great opportunity to participate in a mystery visit!</p>\r\n\r\n<p>Best regards,<br>{{app_name}}</p>', NULL, NULL, '2025-11-21 23:02:09', '2025-11-21 23:02:09', NULL);

