(2, '409114f6-664d-4ce5-aac6-4453e17-fsd2631e', 12, 1, '\"{\\\"title\\\":\\\"Algemene Vragenlijst 9.0 3.0\\\",\\\"score\\\":4,\\\"question_id\\\":\\\"4\\\",\\\"branch_id\\\":\\\"1\\\",\\\"category\\\":{\\\"default\\\":\\\"Reserveren en Media\\\",\\\"1751806738404\\\":\\\"Gastgerichtheid\\\",\\\"1751807217540\\\":\\\"Verkoop\\\",\\\"1751807493376\\\":\\\"Hygi\\\\u00ebne-Netheid\\\",\\\"1751807675054\\\":\\\"In- en Exterieur\\\",\\\"1751807967952\\\":\\\"Sanitair\\\",\\\"1751808265568\\\":\\\"Overige\\\",\\\"1751806310044\\\":\\\"Entree\\\"},\\\"question\\\":{\\\"default\\\":[{\\\"qId\\\":1751806145710,\\\"title\\\":\\\"De website is gebruiksvriendelijk, heeft een goede uitstraling, design en geeft overzichtelijke informatie\\\",\\\"answer\\\":\\\"3\\\",\\\"score\\\":\\\"\\\",\\\"categoryName\\\":\\\"Reserveren en Media\\\",\\\"comment\\\":null,\\\"photo\\\":[],\\\"na\\\":\\\"0\\\"},{\\\"qId\\\":1751806184412,\\\"title\\\":\\\"Mijn ervaring met de reservering was goed (telefonisch of via de website)\\\",\\\"answer\\\":\\\"2\\\",\\\"score\\\":\\\"\\\",\\\"categoryName\\\":\\\"Reserveren en Media\\\",\\\"comment\\\":null,\\\"photo\\\":[],\\\"na\\\":\\\"0\\\"},{\\\"qId\\\":1751806206436,\\\"title\\\":\\\"De social media van deze zaak ziet er aantrekkelijk uit  (FB, Insta, etc)\\\",\\\"answer\\\":\\\"4\\\",\\\"score\\\":\\\"\\\",\\\"categoryName\\\":\\\"Reserveren en Media\\\",\\\"comment\\\":null,\\\"photo\\\":[],\\\"na\\\":\\\"0\\\"}],\\\"1751806738404\\\":[{\\\"qId\\\":1751806768981,\\\"title\\\":\\\"De medewerker vraagt binnen een acceptabele tijd naar drankjes\\\",\\\"answer\\\":\\\"nee\\\",\\\"score\\\":\\\"0\\\",\\\"categoryName\\\":\\\"Gastgerichtheid\\\",\\\"comment\\\":null,\\\"photo\\\":[],\\\"na\\\":\\\"0\\\"},{\\\"qId\\\":1751806796722,\\\"title\\\":\\\"De wijnkaart wordt aangeboden en de medewerker geeft advies (indien gevraagd)\\\",\\\"answer\\\":\\\"\\\",\\\"score\\\":\\\"\\\",\\\"categoryName\\\":\\\"Gastgerichtheid\\\",\\\"comment\\\":null,\\\"photo\\\":